CREATE TABLE dere_upload_batch (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, entity_id BIGINT NOT NULL, source_name VARCHAR(255) NOT NULL, file_count INT NOT NULL, valid_count INT NOT NULL, invalid_count INT NOT NULL, total_bytes BIGINT NOT NULL, created_at TIMESTAMP NOT NULL, FOREIGN KEY(user_id) REFERENCES dere_user(id), FOREIGN KEY(entity_id) REFERENCES dere_entity(id));

